=== FILE: apb_regs.v ===
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements microarchitecture.md for interface_spec.md.
// Zero wait states, no state machine; the only state is the four registers.
module apb_regs #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam STRB_WIDTH = DATA_WIDTH / 8;

    // Access phase: the one cycle in which the transfer completes (pready is always high).
    wire apb_access;
    assign apb_access = psel && penable;

    // Address decode: word aligned and inside 0x0..0xC.
    wire addr_mapped;
    assign addr_mapped = (paddr[1:0] == 2'b00) &&
                         (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});

    wire [1:0] reg_idx;
    assign reg_idx = paddr[3:2];

    wire wr_en;
    assign wr_en = apb_access && pwrite && addr_mapped;

    wire rd_en;
    assign rd_en = apb_access && !pwrite && addr_mapped;

    // Byte-lane write mask from the strobes.
    wire [DATA_WIDTH-1:0] wmask;
    genvar g;
    generate
        for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_mask
            assign wmask[8*g +: 8] = {8{pstrb[g]}};
        end
    endgenerate

    // Register file: four separate flops.
    reg [DATA_WIDTH-1:0] reg0_q;
    reg [DATA_WIDTH-1:0] reg1_q;
    reg [DATA_WIDTH-1:0] reg2_q;
    reg [DATA_WIDTH-1:0] reg3_q;

    // Next values: strobed bytes from pwdata, other bytes kept.
    wire [DATA_WIDTH-1:0] reg0_d;
    wire [DATA_WIDTH-1:0] reg1_d;
    wire [DATA_WIDTH-1:0] reg2_d;
    wire [DATA_WIDTH-1:0] reg3_d;
    assign reg0_d = (reg0_q & ~wmask) | (pwdata & wmask);
    assign reg1_d = (reg1_q & ~wmask) | (pwdata & wmask);
    assign reg2_d = (reg2_q & ~wmask) | (pwdata & wmask);
    assign reg3_d = (reg3_q & ~wmask) | (pwdata & wmask);

    always @(posedge pclk) begin
        if (!presetn) begin
            reg0_q <= {DATA_WIDTH{1'b0}};
            reg1_q <= {DATA_WIDTH{1'b0}};
            reg2_q <= {DATA_WIDTH{1'b0}};
            reg3_q <= {DATA_WIDTH{1'b0}};
        end else begin
            if (wr_en && (reg_idx == 2'd0)) reg0_q <= reg0_d;
            if (wr_en && (reg_idx == 2'd1)) reg1_q <= reg1_d;
            if (wr_en && (reg_idx == 2'd2)) reg2_q <= reg2_d;
            if (wr_en && (reg_idx == 2'd3)) reg3_q <= reg3_d;
        end
    end

    // Read multiplexer.
    reg [DATA_WIDTH-1:0] rd_mux;
    always @* begin
        case (reg_idx)
            2'd0:    rd_mux = reg0_q;
            2'd1:    rd_mux = reg1_q;
            2'd2:    rd_mux = reg2_q;
            2'd3:    rd_mux = reg3_q;
            default: rd_mux = {DATA_WIDTH{1'b0}};
        endcase
    end

    assign prdata  = rd_en ? rd_mux : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = apb_access && !addr_mapped;

endmodule
=== END FILE ===
