// apb_regs_tb: directed self-checking testbench for apb_regs.
// Inputs change after the falling edge; outputs are checked 1 time unit later,
// well before the next rising edge.
module apb_regs_tb;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    integer        passed;
    integer        failed;
    reg [8*64-1:0] nonce;
    reg [31:0]     model [0:3];
    integer        i;
    integer        k;
    reg [31:0]     d;
    reg [7:0]      a;

    apb_regs #(
        .ADDR_WIDTH(8),
        .DATA_WIDTH(32)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // Independent decode model: word aligned and inside 0x0..0xC.
    function tb_mapped(input [7:0] addr);
        tb_mapped = (addr[1:0] == 2'b00) && (addr[7:4] == 4'h0);
    endfunction

    // Independent byte-merge model.
    function [31:0] merge_m(input [31:0] o, input [31:0] w, input [3:0] s);
        merge_m = { (s[3] ? w[31:24] : o[31:24]),
                    (s[2] ? w[23:16] : o[23:16]),
                    (s[1] ? w[15:8]  : o[15:8]),
                    (s[0] ? w[7:0]   : o[7:0]) };
    endfunction

    // Unmapped address list: misaligned, then out of range.
    function [7:0] unm_addr(input [3:0] n);
        case (n)
            4'd0:    unm_addr = 8'h01;
            4'd1:    unm_addr = 8'h02;
            4'd2:    unm_addr = 8'h03;
            4'd3:    unm_addr = 8'h05;
            4'd4:    unm_addr = 8'h0A;
            4'd5:    unm_addr = 8'h0F;
            4'd6:    unm_addr = 8'h10;
            4'd7:    unm_addr = 8'h14;
            4'd8:    unm_addr = 8'h18;
            4'd9:    unm_addr = 8'h1C;
            4'd10:   unm_addr = 8'h40;
            4'd11:   unm_addr = 8'h80;
            4'd12:   unm_addr = 8'hFC;
            4'd13:   unm_addr = 8'hFF;
            4'd14:   unm_addr = 8'h11;
            default: unm_addr = 8'hC4;
        endcase
    endfunction

    task check1(input got, input expv, input [8*32-1:0] what);
        begin
            if (got === expv) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("%0s: got %b expected %b", what, got, expv);
            end
        end
    endtask

    task check32(input [31:0] got, input [31:0] expv, input [8*32-1:0] what);
        begin
            if (got === expv) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("%0s: got %h expected %h", what, got, expv);
            end
        end
    endtask

    task check_quiet(input [8*32-1:0] what);
        begin
            check32(prdata, 32'h0, what);
            check1(pslverr, 1'b0, what);
        end
    endtask

    // Idle cycles with junk on address and data, outputs must stay quiet.
    task idle(input [3:0] n);
        integer c;
        begin
            for (c = 0; c < n; c = c + 1) begin
                @(negedge pclk);
                psel    = 1'b0;
                penable = 1'b0;
                pwrite  = 1'b0;
                pstrb   = 4'h0;
                paddr   = 8'h5A;
                pwdata  = 32'h0BADF00D;
                #1;
                check_quiet("idle quiet");
            end
        end
    endtask

    // One APB transfer: setup cycle, then one access cycle. Back to back by default.
    task xfer(input wr, input [7:0] addr, input [31:0] wdata, input [3:0] strb);
        reg        exp_err;
        reg [31:0] exp_rd;
        begin
            exp_err = !tb_mapped(addr);
            exp_rd  = (wr || exp_err) ? 32'h0 : model[addr[3:2]];
            // Setup phase.
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = wr;
            paddr   = addr;
            pwdata  = wdata;
            pstrb   = wr ? strb : 4'h0;
            #1;
            check_quiet("setup quiet");
            // Access phase.
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check1(pready, 1'b1, "access pready");
            check1(pslverr, exp_err, "access pslverr");
            check32(prdata, exp_rd, "access prdata");
            if (wr && !exp_err) begin
                model[addr[3:2]] = merge_m(model[addr[3:2]], wdata, strb);
            end
        end
    endtask

    task read_all;
        integer r;
        reg [7:0] ra;
        begin
            for (r = 0; r < 4; r = r + 1) begin
                ra = {4'h0, r[1:0], 2'b00};
                xfer(1'b0, ra, 32'h0, 4'h0);
            end
        end
    endtask

    task read_all_gapped;
        integer r;
        reg [7:0] ra;
        begin
            for (r = 0; r < 4; r = r + 1) begin
                ra = {4'h0, r[1:0], 2'b00};
                xfer(1'b0, ra, 32'h0, 4'h0);
                idle(4'd2);
            end
        end
    endtask

    task do_reset(input [3:0] n);
        integer c;
        begin
            @(negedge pclk);
            presetn = 1'b0;
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            pstrb   = 4'h0;
            #1;
            check_quiet("reset quiet");
            for (c = 0; c < n; c = c + 1) begin
                @(negedge pclk);
                #1;
                check_quiet("reset quiet");
            end
            for (c = 0; c < 4; c = c + 1) begin
                model[c[1:0]] = 32'h0;
            end
            @(negedge pclk);
            presetn = 1'b1;
            #1;
            check_quiet("post-reset quiet");
        end
    endtask

    // Watchdog.
    initial begin
        #200000;
        failed = failed + 1;
        $error("watchdog timeout");
        $finish;
    end

    initial begin
        passed  = 0;
        failed  = 0;
        nonce   = {(8*64){1'b0}};
        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'h00;
        pwdata  = 32'h0;
        pstrb   = 4'h0;
        for (i = 0; i < 4; i = i + 1) begin
            model[i[1:0]] = 32'h0;
        end

        // 1. Reset and reset values.
        do_reset(4'd4);
        read_all;

        // 2. Full-word writes to every register, back to back, then read back.
        xfer(1'b1, 8'h00, 32'h01234567, 4'hF);
        xfer(1'b1, 8'h04, 32'h89ABCDEF, 4'hF);
        xfer(1'b1, 8'h08, 32'hA5A55A5A, 4'hF);
        xfer(1'b1, 8'h0C, 32'hFEDCBA98, 4'hF);
        read_all;

        // 3. Read back with idle gaps.
        idle(4'd3);
        read_all_gapped;

        // 4. Every strobe pattern (including none) on REG1, each read back at once.
        xfer(1'b1, 8'h04, 32'hCAFEBABE, 4'hF);
        for (k = 0; k < 16; k = k + 1) begin
            d = {k[3:0], 4'h1, k[3:0], 4'h2, k[3:0], 4'h3, k[3:0], 4'h4};
            xfer(1'b1, 8'h04, d, k[3:0]);
            xfer(1'b0, 8'h04, 32'h0, 4'h0);
        end
        read_all;

        // 5. Partial writes on the other registers, mixed with reads, with a gap.
        xfer(1'b1, 8'h00, 32'h11111111, 4'h1);
        xfer(1'b0, 8'h00, 32'h0, 4'h0);
        idle(4'd1);
        xfer(1'b1, 8'h08, 32'h22222222, 4'h6);
        xfer(1'b1, 8'h0C, 32'h33333333, 4'h8);
        xfer(1'b0, 8'h08, 32'h0, 4'h0);
        xfer(1'b0, 8'h0C, 32'h0, 4'h0);

        // 6. PSLVERR policy: unmapped writes change nothing, unmapped reads return zero.
        for (k = 0; k < 16; k = k + 1) begin
            a = unm_addr(k[3:0]);
            xfer(1'b1, a, 32'hDEADBEEF, 4'hF);
        end
        read_all;
        for (k = 0; k < 16; k = k + 1) begin
            a = unm_addr(k[3:0]);
            xfer(1'b0, a, 32'h0, 4'h0);
            if (k[0]) idle(4'd1);
        end
        // Mapped access directly after an erroring one.
        xfer(1'b1, 8'h10, 32'h0F0F0F0F, 4'hF);
        xfer(1'b1, 8'h00, 32'h0F0F0F0F, 4'hF);
        xfer(1'b0, 8'h13, 32'h0, 4'h0);
        xfer(1'b0, 8'h00, 32'h0, 4'h0);
        read_all;

        // 7. Reset again: registers return to zero.
        idle(4'd2);
        do_reset(4'd3);
        read_all;
        xfer(1'b1, 8'h0C, 32'h5A5A5A5A, 4'hF);
        xfer(1'b0, 8'h0C, 32'h0, 4'h0);
        idle(4'd2);

        // Verdict.
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = {(8*64){1'b0}};
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
